def nearest_fill(grid, marker, fill):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    def lines(cells):
        # cells: list of coordinates along one axis
        for k,(i,j) in enumerate(cells):
            best=None
            for k2,(i2,j2) in enumerate(cells):
                if k2==k: continue
                if i==i2 or j==j2:
                    d=abs(i-i2)+abs(j-j2)
                    if best is None or d<best[0]: best=(d,i2,j2)
            if best:
                _,i2,j2=best
                for a in range(min(i,i2)+1,max(i,i2)):
                    if i==i2: g[i][a]=fill
                for a in range(min(j,j2)+1,max(j,j2)):
                    if j==j2: g[a][j]=fill
    ones=[(i,j) for i in range(h) for j in range(w) if g[i][j]==marker]
    lines(ones)
    return g
